"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import re
from dataclasses import dataclass


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()
    original: str = ""

    def __lt__(self, other: Version) -> bool:
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        if not self.prerelease and not other.prerelease:
            return False
        if not self.prerelease:
            return False
        if not other.prerelease:
            return True

        for s, o in zip(self.prerelease, other.prerelease):
            s_is_digit = s.isdigit()
            o_is_digit = o.isdigit()

            if s_is_digit and o_is_digit:
                s_num = int(s)
                o_num = int(o)
                if s_num != o_num:
                    return s_num < o_num
            elif s_is_digit:
                return True
            elif o_is_digit:
                return False
            else:
                if s != o:
                    return s < o

        return len(self.prerelease) < len(other.prerelease)

    def __le__(self, other: Version) -> bool:
        return self == other or self < other

    def __gt__(self, other: Version) -> bool:
        return other < self

    def __ge__(self, other: Version) -> bool:
        return self == other or other < self

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return False
        return (
            self.major == other.major
            and self.minor == other.minor
            and self.patch == other.patch
            and self.prerelease == other.prerelease
        )


def parse_version(s: str) -> Version:
    pattern = r"^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z\-\.]+))?(?:\+([0-9A-Za-z\-\.]+))?$"
    match = re.match(pattern, s)
    if not match:
        raise RangeError(f"Invalid version: {s}")

    major_str, minor_str, patch_str, prerelease_str, build_str = match.groups()

    if (len(major_str) > 1 and major_str[0] == "0") or \
       (len(minor_str) > 1 and minor_str[0] == "0") or \
       (len(patch_str) > 1 and patch_str[0] == "0"):
        raise RangeError(f"Invalid version: {s}")

    major, minor, patch = int(major_str), int(minor_str), int(patch_str)

    prerelease = ()
    if prerelease_str:
        parts = prerelease_str.split(".")
        for part in parts:
            if not part or not re.match(r"^[0-9A-Za-z\-]+$", part):
                raise RangeError(f"Invalid prerelease: {prerelease_str}")
            if part.isdigit() and len(part) > 1 and part[0] == "0":
                raise RangeError(f"Invalid numeric identifier: {part}")
        prerelease = tuple(parts)

    build = ()
    if build_str:
        parts = build_str.split(".")
        for part in parts:
            if not part or not re.match(r"^[0-9A-Za-z\-]+$", part):
                raise RangeError(f"Invalid build: {build_str}")
        build = tuple(parts)

    return Version(major, minor, patch, prerelease, build, s)


@dataclass
class Comparator:
    op: str
    version: Version


def parse_partial_version(s: str) -> tuple[int, int, int] | tuple[int, int] | tuple[int]:
    if s in ("*", "x", "X"):
        return ()

    parts = s.split(".")
    result = []
    for i, part in enumerate(parts):
        if part in ("x", "X", "*"):
            if i < len(parts) - 1:
                raise RangeError(f"Wildcard not at end: {s}")
            return tuple(result)
        try:
            result.append(int(part))
        except ValueError:
            raise RangeError(f"Invalid version component: {part}")

    return tuple(result)


def desugar_comparator(comp_str: str) -> list[Comparator]:
    comp_str = comp_str.strip()
    if not comp_str:
        return [Comparator(">=", Version(0, 0, 0))]

    if comp_str in ("*", "x", "X"):
        return [Comparator(">=", Version(0, 0, 0))]

    if comp_str[0] in "^~<>":
        if comp_str[0] == "^":
            return desugar_caret(comp_str[1:])
        elif comp_str[0] == "~":
            return desugar_tilde(comp_str[1:])
        else:
            op_match = re.match(r"^(>=|>|<=|<)", comp_str)
            if not op_match:
                raise RangeError(f"Invalid comparator: {comp_str}")
            op = op_match.group(1)
            version_str = comp_str[len(op) :].strip()
            v = parse_version(version_str)
            return [Comparator(op, v)]
    else:
        eq_match = re.match(r"^=(.*)$", comp_str)
        if eq_match:
            comp_str = eq_match.group(1).strip()

        partial = parse_partial_version(comp_str)

        if len(partial) == 3:
            v = parse_version(comp_str)
            return [Comparator("=", v)]
        elif len(partial) == 2:
            major, minor = partial
            lower = Version(major, minor, 0)
            upper = Version(major, minor + 1, 0)
            return [Comparator(">=", lower), Comparator("<", upper)]
        elif len(partial) == 1:
            major = partial[0]
            lower = Version(major, 0, 0)
            upper = Version(major + 1, 0, 0)
            return [Comparator(">=", lower), Comparator("<", upper)]
        else:
            return [Comparator(">=", Version(0, 0, 0))]


def desugar_caret(version_str: str) -> list[Comparator]:
    version_str = version_str.strip()
    if version_str.startswith("^") or version_str.startswith("~"):
        raise RangeError(f"Invalid caret range: ^{version_str}")

    if "-" in version_str or "+" in version_str:
        lower_v = parse_version(version_str)
        major, minor, patch = lower_v.major, lower_v.minor, lower_v.patch

        if major != 0:
            upper_v = Version(major + 1, 0, 0)
        elif minor != 0:
            upper_v = Version(0, minor + 1, 0)
        else:
            upper_v = Version(0, 0, patch + 1)

        return [Comparator(">=", lower_v), Comparator("<", upper_v)]

    partial = parse_partial_version(version_str)

    if not partial:
        raise RangeError(f"Invalid caret range: ^{version_str}")

    if len(partial) == 1:
        major = partial[0]
        lower_v = Version(major, 0, 0)
        upper_v = Version(major + 1, 0, 0)
    elif len(partial) == 2:
        major, minor = partial
        lower_v = Version(major, minor, 0)
        upper_v = Version(major + 1, 0, 0)
    else:
        major, minor, patch = partial[0], partial[1], partial[2]
        lower_v = Version(major, minor, patch)

        if major != 0:
            upper_v = Version(major + 1, 0, 0)
        elif minor != 0:
            upper_v = Version(0, minor + 1, 0)
        else:
            upper_v = Version(0, 0, patch + 1)

    return [Comparator(">=", lower_v), Comparator("<", upper_v)]


def desugar_tilde(version_str: str) -> list[Comparator]:
    version_str = version_str.strip()
    if version_str.startswith("^") or version_str.startswith("~"):
        raise RangeError(f"Invalid tilde range: ~{version_str}")

    if "-" in version_str or "+" in version_str:
        lower_v = parse_version(version_str)
        major, minor = lower_v.major, lower_v.minor
        upper_v = Version(major, minor + 1, 0)
        return [Comparator(">=", lower_v), Comparator("<", upper_v)]

    partial = parse_partial_version(version_str)

    if not partial:
        raise RangeError(f"Invalid tilde range: ~{version_str}")

    if len(partial) == 1:
        major = partial[0]
        lower_v = Version(major, 0, 0)
        upper_v = Version(major + 1, 0, 0)
    elif len(partial) == 2:
        major, minor = partial
        lower_v = Version(major, minor, 0)
        upper_v = Version(major, minor + 1, 0)
    else:
        major, minor, patch = partial[0], partial[1], partial[2]
        lower_v = Version(major, minor, patch)
        upper_v = Version(major, minor + 1, 0)

    return [Comparator(">=", lower_v), Comparator("<", upper_v)]


def parse_hyphen_range(parts: list[str]) -> list[Comparator]:
    if len(parts) != 3 or parts[1] != "-":
        raise RangeError("Hyphen range must be exactly 'A - B'")

    lower_str = parts[0].strip()
    upper_str = parts[2].strip()

    lower_partial = parse_partial_version(lower_str)
    upper_partial = parse_partial_version(upper_str)

    if not lower_partial or not upper_partial:
        raise RangeError("Hyphen bounds must have at least a major component")

    if len(lower_partial) == 1:
        lower_v = Version(lower_partial[0], 0, 0)
    elif len(lower_partial) == 2:
        lower_v = Version(lower_partial[0], lower_partial[1], 0)
    else:
        lower_v = parse_version(lower_str)

    if len(upper_partial) == 3:
        upper_v = parse_version(upper_str)
        return [Comparator(">=", lower_v), Comparator("<=", upper_v)]
    else:
        upper_partial_list = list(upper_partial)
        upper_partial_list[-1] += 1
        while len(upper_partial_list) < 3:
            upper_partial_list.append(0)
        upper_v = Version(upper_partial_list[0], upper_partial_list[1], upper_partial_list[2])
        return [Comparator(">=", lower_v), Comparator("<", upper_v)]


def parse_comparator_set(set_str: str) -> list[Comparator]:
    set_str = set_str.strip()
    if not set_str:
        return [Comparator(">=", Version(0, 0, 0))]

    parts = set_str.split()
    if len(parts) == 3 and parts[1] == "-":
        return parse_hyphen_range(parts)

    comparators = []
    i = 0
    while i < len(parts):
        part = parts[i]

        if part in ("*", "x", "X"):
            comparators.extend(desugar_comparator(part))
            i += 1
        elif part == "":
            i += 1
        elif part[0] in "^~<>=":
            comparators.extend(desugar_comparator(part))
            i += 1
        elif re.match(r"^\d", part) or part in ("x", "X", "*"):
            if "-" in part or "+" in part:
                v = parse_version(part)
                comparators.append(Comparator("=", v))
            else:
                partial = parse_partial_version(part)
                if len(partial) == 3:
                    v = parse_version(part)
                    comparators.append(Comparator("=", v))
                elif len(partial) == 2:
                    major, minor = partial
                    comparators.append(Comparator(">=", Version(major, minor, 0)))
                    comparators.append(Comparator("<", Version(major, minor + 1, 0)))
                elif len(partial) == 1:
                    major = partial[0]
                    comparators.append(Comparator(">=", Version(major, 0, 0)))
                    comparators.append(Comparator("<", Version(major + 1, 0, 0)))
                else:
                    comparators.append(Comparator(">=", Version(0, 0, 0)))
            i += 1
        else:
            raise RangeError(f"Invalid comparator: {part}")

    return comparators


def satisfies_comparator(version: Version, comp: Comparator) -> bool:
    v = comp.version
    if comp.op == "=":
        return version == v
    elif comp.op == ">=":
        return version >= v
    elif comp.op == ">":
        return version > v
    elif comp.op == "<=":
        return version <= v
    elif comp.op == "<":
        return version < v
    else:
        raise RangeError(f"Unknown operator: {comp.op}")


def satisfies_comparator_set(version: Version, comparators: list[Comparator]) -> bool:
    for comp in comparators:
        if not satisfies_comparator(version, comp):
            return False

    if not version.prerelease:
        return True

    for comp in comparators:
        if comp.version.prerelease and (
            comp.version.major == version.major
            and comp.version.minor == version.minor
            and comp.version.patch == version.patch
        ):
            return True

    return False


def parse_range_expression(range_expr: str) -> list[list[Comparator]]:
    range_expr = range_expr.strip()
    if not range_expr:
        return [[Comparator(">=", Version(0, 0, 0))]]

    sets = range_expr.split("||")
    result = []

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            raise RangeError("Empty comparator set in union")
        result.append(parse_comparator_set(set_str))

    return result


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    parsed_versions = []
    for v_str in versions:
        parsed_versions.append((parse_version(v_str), v_str))

    try:
        comparator_sets = parse_range_expression(range_expr)
    except RangeError:
        raise

    max_version = None
    max_original = None

    for parsed_v, original_v in parsed_versions:
        for comparator_set in comparator_sets:
            if satisfies_comparator_set(parsed_v, comparator_set):
                if max_version is None or parsed_v > max_version:
                    max_version = parsed_v
                    max_original = original_v
                break

    return max_original
